// === Tab: mySketch ===
var u, v;
var pause, showBasis;
var lastColor, currentColor, nextColor, colorT;

function preload(){
	theShader = createShader(vertShader, fragShader);
}

function setup() {
	createCanvas(1112, 834, WEBGL);
	background(100);
	u = createVector(0.1,0.1);
	v = createVector(0.1*sqrt(2),-0.1*sqrt(2));
	pause = false;
	showBasis = false;
	currentColor = createVector(1,1,1);
}

/**
 * Return the smallest vector of the form u+k*v where k is an integer.
 */
function reduceFirstVector(u, v){
	var uu = u.magSq();

	var w = p5.Vector.sub(u,v);
	var ww = w.magSq();
	while (ww<uu){
		u = w;
		uu = ww;

		w = p5.Vector.sub(u,v);
		ww = w.magSq();
	}

	w = p5.Vector.add(u,v);
	ww = w.magSq();
	while (ww<uu){
		u = w;
		uu = ww;

		w = p5.Vector.add(u,v);
		ww = w.magSq();
	}

	return u;
}

/**
 * Update the basis u,v such that they would contain the smallest vector in the lattice 
 * that they generate + second smallest vector which is not a multiple of the first vector.
 */
function minimalBasis(){
	u = reduceFirstVector(u,v);
	var w = reduceFirstVector(v,u);
	var iteration = 0;
	while (!w.equals(v)){
		if (iteration == 10)
			return;
		iteration--;

		v = u;
		u = w;
		w = reduceFirstVector(v,u);
	}
}

function draw() {

	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_show_basis", showBasis);

	theShader.setUniform("u_color", [currentColor.x, currentColor.y, currentColor.z]);
	if (nextColor!=null){
		currentColor = p5.Vector.lerp(lastColor, nextColor, colorT);
		colorT+=0.01;
		if (colorT>=1){
			nextColor = null;
			colorT = 0;
		}
	}

	var d = u.x*v.y-u.y*v.x;
	theShader.setUniform("u_vec1_functional", [v.y/d,-v.x/d]);
	theShader.setUniform("u_vec2_functional", [-u.y/d, u.x/d]);
	theShader.setUniform("u_vec1", [u.x, u.y]);
	theShader.setUniform("u_vec2", [v.x, v.y]);

	shader(theShader);
	rect(0,0,width,height);

	if (pause){
		if (keyIsDown(LEFT_ARROW))
			move(0.01);
		if (keyIsDown(RIGHT_ARROW))
			move(-0.01);
	} else {
		move(0.01);
	}
}

function randomColor(){
	colorT = 0;
	var values = [random(0.8,1), random(0.4,1), random(0,1)];

	var first = random([0,1,2]);
	var temp = values[0];
	values[0] = values[first];
	values[first] = temp;

	var second = random([1,2]);
	temp = values[1];
	values[1] = values[second];
	values[second] = temp;

	nextColor = createVector(values[0], values[1], values[2]);
	lastColor = currentColor;
}

function move(dx){
	var a = exp(dx);
	var b = 1/a;
	u.x*=a;
	u.y*=b;
	v.x*=a;
	v.y*=b;
	minimalBasis();
}

function keyPressed(){
	if (key == 'p'){
		pause = !pause;
	}
	if (key == 'b'){
		showBasis = !showBasis;
	}
	if (key == 'r'){
		randomColor();
	}
	if (key == 's'){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
	}
}

// === Tab: frag shader ===
let fragShader = `
#ifdef GL_ES 
precision mediump float;
#endif

uniform vec2 u_vec1;
uniform vec2 u_vec2;
uniform vec2 u_vec1_functional;
uniform vec2 u_vec2_functional;
uniform vec2 u_resolution;
uniform vec3 u_color;
uniform bool u_show_basis;

bool drawBasisVectors(vec2 v){
		if (distance(v, u_vec1)<0.005){
			gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);
			return true;
		}
		if (distance(v, u_vec2)<0.005){
			gl_FragColor = vec4(0.0, 1.0, 0.0, 1.0);
			return true;
		}
		if (length(v)<0.005){
			gl_FragColor = vec4(0.0, 0.0, 1.0,  1.0);
			return true;
		}
		return false;
}

vec2 toFundamentalDomain(vec2 v){
		float coef1 = u_vec1_functional.x*v.x + u_vec1_functional.y*v.y;
		coef1 -= floor(coef1);

		float coef2 = u_vec2_functional.x*v.x + u_vec2_functional.y*v.y;
		coef2 -= floor(coef2);

		return coef1*u_vec1 + coef2*u_vec2;	
}

void main() {
		vec2 normalizePos = gl_FragCoord.xy/u_resolution.xy;
		normalizePos/=3.0;
		normalizePos -= 0.5; // move the origin to the center of the screen.

		vec2 v = normalizePos;
		v.x *= (u_resolution.x/u_resolution.y); // fix the dimension

		if (u_show_basis){
			if (drawBasisVectors(v))
				return;
		}

		vec2 vv = toFundamentalDomain(v);

		// find normalized distance from vertices of the parallelogram.
		float normalization = sqrt(abs(u_vec1.x*u_vec2.y-u_vec1.y*u_vec2.x))*0.6;
		float d1 = min(distance(vv,u_vec2), distance(vv,u_vec1));
		float d2 = min(distance(vv,u_vec1 + u_vec2), distance(vv,vec2(0,0)));
		float d = min(d1, d2)/normalization;

		float density = 1.0 - sqrt(d);

    gl_FragColor = vec4(u_color.r*density, u_color.g*density*density, u_color.b*density, 1.0);

}
`

// === Tab: vert shader ===
let vertShader = `

#ifdef GL_ES //for browser or mobile
//can change mediump to either lowp or highp.
precision mediump float;
#endif

// Input:
attribute vec3 aPosition;  //position of the vertex

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);

	// This is a weird behaviour in p5. Need to scale the vertices so they will appear in the right place.
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

	//Output:
  gl_Position = positionVec4;
}`;

